create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','admin','analyst','viewer');
create type public.keyword_type as enum ('include','exclude','exact','related');
create type public.sentiment_type as enum ('positive','neutral','negative','unknown');

create table profiles (id uuid primary key default gen_random_uuid(), user_id uuid unique not null references auth.users(id) on delete cascade, name text not null, avatar_url text, role text not null default 'user', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text unique not null, logo_url text, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table organization_members (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role member_role not null default 'viewer', created_at timestamptz not null default now(), unique(organization_id,user_id));
create table projects (id uuid primary key default gen_random_uuid(), organization_id uuid not null references organizations(id) on delete cascade, name text not null, description text, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table monitors (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, name text not null, description text, status text not null default 'active', language text not null default 'pt-BR', country text not null default 'BR', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table monitor_keywords (id uuid primary key default gen_random_uuid(), monitor_id uuid not null references monitors(id) on delete cascade, keyword text not null, type keyword_type not null default 'include', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(monitor_id,keyword,type));
create table sources (id uuid primary key default gen_random_uuid(), organization_id uuid references organizations(id) on delete cascade, name text not null, domain text, source_type text not null check(source_type in ('rss','news','youtube','telegram','reddit','future')), rss_url text, site_url text, country text default 'BR', state text, category text not null default 'outros', active boolean not null default true, last_checked_at timestamptz, check_interval integer not null default 30 check(check_interval>=5), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table articles (id uuid primary key default gen_random_uuid(), source_id uuid not null references sources(id), external_id text, title text not null, description text, content text, author text, url text not null, canonical_url text not null, image_url text, published_at timestamptz, collected_at timestamptz not null default now(), language text default 'pt-BR', category text, hash text not null, search_vector tsvector generated always as (to_tsvector('portuguese',coalesce(title,'')||' '||coalesce(description,'')||' '||coalesce(content,''))) stored, created_at timestamptz not null default now(), unique(canonical_url), unique(hash));
create table mentions (id uuid primary key default gen_random_uuid(), monitor_id uuid not null references monitors(id) on delete cascade, article_id uuid not null references articles(id) on delete cascade, keyword_id uuid references monitor_keywords(id) on delete set null, matched_text text, relevance_score numeric(4,3) not null default 0, created_at timestamptz not null default now(), unique(monitor_id,article_id,keyword_id));
create table article_entities (id uuid primary key default gen_random_uuid(), article_id uuid not null references articles(id) on delete cascade, entity text not null, entity_type text not null check(entity_type in ('person','organization','location','event','product','other')), confidence numeric(4,3), created_at timestamptz not null default now());
create table article_topics (id uuid primary key default gen_random_uuid(), article_id uuid not null references articles(id) on delete cascade, topic text not null, score numeric(4,3), created_at timestamptz not null default now());
create table sentiment_analysis (id uuid primary key default gen_random_uuid(), article_id uuid not null references articles(id) on delete cascade, sentiment sentiment_type not null default 'unknown', score numeric(5,4), confidence numeric(4,3), provider text not null, model text not null, created_at timestamptz not null default now());
create table alerts (id uuid primary key default gen_random_uuid(), monitor_id uuid not null references monitors(id) on delete cascade, name text not null, type text not null check(type in ('keyword_spike','negative_sentiment','mention_volume','new_mention')), conditions jsonb not null default '{}', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table alert_events (id uuid primary key default gen_random_uuid(), alert_id uuid not null references alerts(id) on delete cascade, monitor_id uuid not null references monitors(id) on delete cascade, payload jsonb not null default '{}', read_at timestamptz, created_at timestamptz not null default now());
create table youtube_videos (id uuid primary key default gen_random_uuid(), source_id uuid references sources(id), video_id text unique not null, channel_id text, channel_name text, title text not null, description text, thumbnail text, published_at timestamptz, views bigint default 0, likes bigint default 0, comments_count bigint default 0, url text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table collection_logs (id uuid primary key default gen_random_uuid(), source_id uuid references sources(id) on delete set null, collector_type text not null, status text not null, items_found integer default 0, new_items integer default 0, duplicates integer default 0, errors jsonb default '[]', duration_ms integer, created_at timestamptz not null default now());

create index articles_published_at_idx on articles(published_at desc); create index articles_source_id_idx on articles(source_id); create index articles_search_idx on articles using gin(search_vector); create index mentions_monitor_id_idx on mentions(monitor_id); create index mentions_article_id_idx on mentions(article_id); create index monitors_project_id_idx on monitors(project_id); create index sources_active_idx on sources(active) where active=true; create index collection_logs_created_idx on collection_logs(created_at desc);

create or replace function public.is_org_member(org_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from organization_members where organization_id=org_id and user_id=auth.uid()) or exists(select 1 from profiles where user_id=auth.uid() and role='global_admin') $$;
alter table profiles enable row level security; alter table organizations enable row level security; alter table organization_members enable row level security; alter table projects enable row level security; alter table monitors enable row level security; alter table monitor_keywords enable row level security; alter table sources enable row level security; alter table articles enable row level security; alter table mentions enable row level security; alter table alerts enable row level security; alter table alert_events enable row level security; alter table collection_logs enable row level security;
create or replace function public.is_global_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where user_id=auth.uid() and role='global_admin') $$;
create or replace function public.can_manage_org(org_id uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from organization_members where organization_id=org_id and user_id=auth.uid() and role in ('owner','admin')) or is_global_admin() $$;
create policy profiles_self on profiles for select using(user_id=auth.uid() or is_global_admin());
create policy profiles_update_self on profiles for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy organizations_member on organizations for select using(is_org_member(id));
create policy organizations_create on organizations for insert with check(created_by=auth.uid());
create policy organizations_manage on organizations for update using(can_manage_org(id)) with check(can_manage_org(id));
create policy members_member on organization_members for select using(is_org_member(organization_id));
create policy members_manage on organization_members for all using(can_manage_org(organization_id)) with check(can_manage_org(organization_id));
create policy members_bootstrap_owner on organization_members for insert with check(user_id=auth.uid() and role='owner' and exists(select 1 from organizations o where o.id=organization_id and o.created_by=auth.uid()));
create policy projects_member on projects for select using(is_org_member(organization_id));
create policy projects_manage on projects for all using(can_manage_org(organization_id)) with check(can_manage_org(organization_id));
create policy monitors_member on monitors for select using(exists(select 1 from projects p where p.id=project_id and is_org_member(p.organization_id)));
create policy monitors_manage on monitors for all using(exists(select 1 from projects p where p.id=project_id and can_manage_org(p.organization_id))) with check(exists(select 1 from projects p where p.id=project_id and can_manage_org(p.organization_id)));
create policy keywords_member on monitor_keywords for select using(exists(select 1 from monitors m join projects p on p.id=m.project_id where m.id=monitor_id and is_org_member(p.organization_id)));
create policy keywords_manage on monitor_keywords for all using(exists(select 1 from monitors m join projects p on p.id=m.project_id where m.id=monitor_id and can_manage_org(p.organization_id))) with check(exists(select 1 from monitors m join projects p on p.id=m.project_id where m.id=monitor_id and can_manage_org(p.organization_id)));
create policy sources_member on sources for select using(organization_id is null or is_org_member(organization_id));
create policy sources_manage on sources for all using(organization_id is not null and can_manage_org(organization_id)) with check(organization_id is not null and can_manage_org(organization_id));
create policy articles_member on articles for select using(exists(select 1 from mentions me join monitors m on m.id=me.monitor_id join projects p on p.id=m.project_id where me.article_id=articles.id and is_org_member(p.organization_id)));
create policy mentions_member on mentions for select using(exists(select 1 from monitors m join projects p on p.id=m.project_id where m.id=monitor_id and is_org_member(p.organization_id)));
create policy alerts_member on alerts for select using(exists(select 1 from monitors m join projects p on p.id=m.project_id where m.id=monitor_id and is_org_member(p.organization_id)));
create policy events_member on alert_events for select using(exists(select 1 from monitors m join projects p on p.id=m.project_id where m.id=monitor_id and is_org_member(p.organization_id)));
create policy logs_admin on collection_logs for select using(exists(select 1 from profiles where user_id=auth.uid() and role='global_admin'));
